(async () => {
  const { promises: fs } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  if (!inputPath) throw new Error('INPUT_PATH env var required');
  await fs.access(inputPath);
  globalThis.inputPath = inputPath;
})();

(async () => {
  const { promises: fs } = await import('node:fs');
  const jspMod = await import('jsparsers');
  const jsp = jspMod.default || jspMod;
  const xmlParser = jsp.xml();
  const content = await fs.readFile(globalThis.inputPath, 'utf8');
  if (typeof xmlParser.load === 'function') {
    xmlParser.load(content);
  }
  if (typeof xmlParser.parse === 'function') {
    xmlParser.parse();
  }
  let tomlStr;
  if (typeof xmlParser.toml === 'function') {
    tomlStr = xmlParser.toml();
  } else if (typeof xmlParser.serialize === 'function') {
    tomlStr = xmlParser.serialize();
  } else {
    throw new Error('TOML conversion method not found on xml parser');
  }
  globalThis.tomlStr = tomlStr;
})();
